package com.example.rokidkeyboardbridge;
import java.lang.reflect.*;import org.json.*;
public class CalendarDispatchDeviceChecks {static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}static Field f(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f;}
 public static int run()throws Exception{MainActivity owner=new MainActivity();Method route=MainActivity.class.getDeclaredMethod("handleSecretaryInbox",String.class);route.setAccessible(true);f("secretaryCard").set(owner,new JSONObject().put("id","synthetic-card"));f("secretaryProposal").set(owner,new JSONObject().put("subject","synthetic"));f("secretaryIntentUnavailable").setBoolean(owner,true);boolean handled=(Boolean)route.invoke(owner,"予約票を添付した。カレンダー「家族予定」に登録して");ok(!handled,"new calendar image request bypasses inbox synchronously without Activity context or provider");ok(f("secretaryCard").get(owner)==null&&f("secretaryProposal").get(owner)==null,"new attachment drops stale inbox referent");ok(!f("secretaryIntentUnavailable").getBoolean(owner),"calendar write no longer disabled by prior routing failure");f("secretaryCard").set(owner,new JSONObject().put("id","synthetic-card"));ok(!(Boolean)route.invoke(owner,"カレンダーに登録して"),"short calendar request continues to calendar writer");ok(f("secretaryCard").get(owner)!=null,"short followup retains intentional selected referent");return n;}}
